This Terraform configuration creates an AWS CodeBuild project using:

- An example IAM service role for CodeBuild
- A GitHub repository as the source
- Example environment variables
- An S3-backed build cache
- CloudWatch Logs permissions
- S3 cache permissions
- A simple inline `buildspec.yml`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the CodeBuild project."
  type        = string
  default     = "example-github-codebuild-project"
}

variable "github_repo_url" {
  description = "GitHub repository URL used as the CodeBuild source."
  type        = string
  default     = "https://github.com/aws-samples/aws-codebuild-samples.git"
}

variable "github_source_version" {
  description = "GitHub branch, tag, or commit to build."
  type        = string
  default     = "main"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}
